use crate::account::Account;
use crate::position::AccountBalance;
use super::latest_for;

/// Accounts the registry declares that have no balance at all — the reason a position is missing a
/// row rather than showing it as zero.
pub fn without_balance(accounts: &[Account], balances: &[AccountBalance]) -> Vec<String> {
    accounts
        .iter()
        .filter(|a| latest_for(balances, &a.id).is_none())
        .map(|a| a.id.clone())
        .collect()
}
